package com.paymentverifier.app
data class ParsedPayment(val provider:String,val amount:Double,val reference:String?,val transactionId:String,val sender:String,val senderPhone:String?)
object SmsParser { fun parse(sender:String?,message:String,providerOverride:String):ParsedPayment? {if(sender.isNullOrBlank()||message.isBlank()||providerOverride.isBlank())return null;val tx=Regex("\\b(?:TrxID|TxnID|Transaction\\s*ID)\\b\\s*[:\\-]?\\s*([A-Za-z0-9][A-Za-z0-9_-]*)",RegexOption.IGNORE_CASE).find(message)?.groupValues?.get(1)?:return null;val amount=Regex("(?:Amount|received)\\s*:?\\s*(?:Tk|BDT|৳)\\s*([0-9,]+(?:\\.[0-9]{1,2})?)",RegexOption.IGNORE_CASE).find(message)?.groupValues?.get(1)?.replace(",","")?.toDoubleOrNull()?:return null;val ref=Regex("\\bRef(?:erence)?\\b\\s*[:\\-]?\\s*([A-Za-z0-9_-]+)",RegexOption.IGNORE_CASE).find(message)?.groupValues?.get(1);val phone=Regex("\\b(?:Sender|from)\\s*:?\\s*(01[3-9]\\d{8}|\\+?8801[3-9]\\d{8})\\b",RegexOption.IGNORE_CASE).find(message)?.groupValues?.get(1);return ParsedPayment(providerOverride.lowercase(),amount,ref,tx,sender.trim(),phone)}}
